/// The name of common action `a`, or None for a character-specific one.
pub fn action(a: i32) -> Option<&'static str> {
    if a < 0 || a as usize >= COUNT {
        return None;
    }
    let (s, e) = (OFF[a as usize] as usize, OFF[a as usize + 1] as usize);
    BLOB.get(s..e)
}

